import { pipeline } from "node:stream/promises";
import type { Readable, Writable } from "node:stream";

async function* transform(src: AsyncIterable<Buffer>): AsyncGenerator<Buffer> {
  for await (const chunk of src) yield compact(chunk);   // pull-paced
}
await pipeline(src as Readable, transform, dst as Writable);

const frames: ReadableStream<Frame> = new ReadableStream<Frame>({
  pull(controller) {                    // called while the queue has room
    const frame = nextFrame();
    if (frame === undefined) return controller.close();
    controller.enqueue(frame);           // the next pull waits for demand
  },
}, new CountQueuingStrategy({ highWaterMark: 8 }));

for await (const frame of frames) consume(frame); // reader sets the pace

